# 发送请求演示的请求
import json

# 直接输出 JSON 动作字符串
print(json.dumps({
    "action": "request_demos"
}))

# 正确的镜像计算
# 对于一个 2x2 方块，左上角 (r,c) 映射到 (r, 14-c)
# 这样最右侧方块 (c=13) 映射到 (14-13)=1，方块占据列 1-2 ✓

rows, cols = 7, 15

def mirror_2x2_square(r, c):
    """映射 2x2 方块左上角的镜像位置"""
    return (r, cols - 1 - c)

original = [(1, 7), (1, 13), (2, 2), (4, 4), (4, 11), (5, 0), (5, 8)]
mirrored = [mirror_2x2_square(r, c) for r, c in original]

print(f"原始方块: {original}")
print(f"镜像方块: {mirrored}")

# 验证边界
for r, c in mirrored:
    if r+1 >= rows or c+1 >= cols:
        print(f"越界: ({r},{c}) 覆盖行 {r}-{r+1}, 列 {c}-{c+1}")

# 检查重叠
def check_overlap(p1, p2):
    r1,c1 = p1
    r2,c2 = p2
    return max(r1,r2) < min(r1+2,r2+2) and max(c1,c2) < min(c1+2,c2+2)

print("\n重叠检查:")
for i in range(len(mirrored)):
    for j in range(i+1, len(mirrored)):
        if check_overlap(mirrored[i], mirrored[j]):
            print(f"重叠: {mirrored[i]} 和 {mirrored[j]}")

# 如果无重叠，构建输出
output = [[0]*cols for _ in range(rows)]
for r,c in mirrored:
    for dr in range(2):
        for dc in range(2):
            output[r+dr][c+dc] = 2

total = sum(row.count(2) for row in output)
print(f"\n2 的总数: {total}")
print("\n输出:")
for row in output:
    print(' '.join(f'{x:2}' for x in row))

